// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/pedidos/{id}/acopio", wrapper.SaldoDeAcopio)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/pedidos/{id}/remitos", wrapper.RemitosDelPedido)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/remitos", wrapper.PrepararRemito)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/remitos/{id}/anular", wrapper.AnularRemito)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/mostrador/pedidos/{id}/remito", wrapper.RemitoDeConstancia)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/remitos/{id}", wrapper.RemitoCompleto)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/remitos/{id}/pdf", wrapper.RemitoPdf)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/remitos/{id}/aviso", wrapper.RemitoParaAvisar)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/firmar/{token}", wrapper.RemitoPorToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/firmar", wrapper.FirmarRemito)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/mi-cuenta/pedidos/{id}/entregas", wrapper.EntregasDeMiPedido)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/envios", wrapper.ZonasDeEnvioDelPanel)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/envios", wrapper.GuardarZonaDeEnvio)

	return m
}

